-- Solidi Småland (Fischer 2023, Occasional Papers 1). Verifierad katalogdata, ingen mock.
CREATE TABLE IF NOT EXISTS public.solidi (
  id uuid primary key default gen_random_uuid(), cat_no int, museum_inv text, ruler text, mint text,
  ric_ref text, issued_from int, issued_to int, weight_g numeric, find_place text, parish text, county text,
  die_link_sides text, die_link_context text, coordinates point, source text default 'Fischer 2023, Solidi of Småland',
  created_at timestamptz default now());
BEGIN;
COMMIT;